import re, random, time, json
from pathlib import Path

repo = Path('/workspace/openhands')
source = repo/'pyproject.toml'
base_out = Path('/workspace/fuzzing/results')
base_out.mkdir(parents=True, exist_ok=True)

core_pkgs = {'zope-interface'}

version_re = re.compile(r'([0-9]+)\.([0-9]+)(?:\.[0-9]+)?')

def rand_version(ver: str) -> str:
    # 60% bias towards ">=x.y", 40% "*"
    if random.random() < 0.6:
        m = version_re.search(ver)
        if m:
            return f'>={m.group(1)}.{m.group(2)}'
        return '>=0.0'
    return '*'

for run_idx in range(1, 6):
    random.seed(int(time.time()*1000) + run_idx)
    text = source.read_text(encoding='utf-8').splitlines(True)
    current_section = ''
    def in_deps(sec: str) -> bool:
        s = sec.strip().lower()
        return s.startswith('[tool.poetry') and s.endswith('.dependencies]')
    out=[]
    for line in text:
        if line.strip().startswith('[') and line.strip().endswith(']'):
            current_section=line
            out.append(line)
            continue
        if not in_deps(current_section):
            out.append(line)
            continue
        if re.match(r'\s*python\s*=\s*', line):
            out.append(line)
            continue
        m = re.match(r'(\s*)([A-Za-z0-9_.\-]+)(\s*=\s*)"([^"]*)"(\s*(#.*)?)\n?$', line)
        if m:
            indent,key,eq,ver,tail = m.group(1), m.group(2), m.group(3), m.group(4), m.group(5)
            if key in core_pkgs or key.startswith('tree-sitter'):
                if ver.strip()=='*' or ver.strip().startswith(('^','>=','~=')):
                    new_ver=ver
                else:
                    new_ver=f'>={ver}'
            else:
                new_ver = rand_version(ver)
            out.append(f"{indent}{key}{eq}\"{new_ver}\"{tail}\n")
            continue
        m2 = re.match(r'(\s*)([A-Za-z0-9_.\-]+)(\s*=\s*)\{(.*)\}(\s*(#.*)?)\n?$', line)
        if m2:
            indent,key,eq,inside,tail = m2.group(1), m2.group(2), m2.group(3), m2.group(4), m2.group(5)
            vm = re.search(r'(version\s*=\s*)"([^"]*)"', inside)
            if vm:
                prefix, ver = vm.group(1), vm.group(2)
                if key in core_pkgs or key.startswith('tree-sitter'):
                    if ver.strip()=='*' or ver.strip().startswith(('^','>=','~=')):
                        new_ver=ver
                    else:
                        new_ver=f'>={ver}'
                else:
                    new_ver = rand_version(ver)
                inside_new = inside[:vm.start(2)] + new_ver + inside[vm.end(2):]
                out.append(f"{indent}{key}{eq}{{{inside_new}}}{tail}\n")
            else:
                out.append(line)
            continue
        out.append(line)
    run_dir = base_out / f'prep-run-{run_idx}-{int(time.time())}'
    run_dir.mkdir(parents=True, exist_ok=True)
    # Save randomized pyproject for this prep-run
    (run_dir/'randomized_pyproject.toml').write_text(''.join(out), encoding='utf-8')
    # Also store a copy of the current repo pyproject as reference
    (run_dir/'original_pyproject.toml').write_text(source.read_text(encoding='utf-8'), encoding='utf-8')
    # Write a quick summary
    star=ge=others=0
    core=[]
    dep_section_re = re.compile(r'^\[tool\.poetry(?:\.group\.[^\]]+)?\.dependencies\]\s*$', re.M)
    lines = ''.join(out).splitlines()
    in_deps=False
    for l in lines:
        if dep_section_re.match(l):
            in_deps=True; continue
        if l.strip().startswith('[') and l.strip().endswith(']'):
            in_deps=False; continue
        if not in_deps: continue
        if re.match(r'\s*python\s*=\s*', l):
            continue
        m = re.match(r'\s*([A-Za-z0-9_.\-]+)\s*=\s*"([^"]+)"', l)
        if m:
            k,v = m.group(1), m.group(2)
            if k in core_pkgs or k.startswith('tree-sitter'):
                core.append({'name':k,'version':v})
            else:
                if v.strip()=='*': star+=1
                elif v.strip().startswith('>='): ge+=1
                else: others+=1
            continue
        m2 = re.match(r'\s*([A-Za-z0-9_.\-]+)\s*=\s*\{(.*)\}', l)
        if m2:
            k,inside = m2.group(1), m2.group(2)
            vm = re.search(r'version\s*=\s*"([^"]+)"', inside)
            if vm:
                v=vm.group(1)
                if k in core_pkgs or k.startswith('tree-sitter'):
                    core.append({'name':k,'version':v})
                else:
                    if v.strip()=='*': star+=1
                    elif v.strip().startswith('>='): ge+=1
                    else: others+=1
    summary = {'STAR': star, 'GE': ge, 'OTHERS': others, 'CORE': core}
    (run_dir/'summary.json').write_text(json.dumps(summary, indent=2), encoding='utf-8')
print('Prepared 5 pre-runs with slight GE bias.')

